+static bool
+write_wbf_packet(capture_file *cf, frame_data *fdata, wtap_rec *rec,
+                 void *argsp)
+{
+    write_packet_callback_args_t *args = (write_packet_callback_args_t *)argsp;
+
+    col_custom_prime_edt(&args->edt, &cf->cinfo);
+    epan_dissect_run(&args->edt, cf->cd_t, rec, fdata, &cf->cinfo);
+    epan_dissect_fill_in_columns(&args->edt, false, true);
+
+    /* Write out the protocol tree in WBF format */
+    write_wbf_proto_tree(NULL, &args->edt, args->fh, args->print_args->print_dissections != print_dissections_none,
+                         args->print_args->wbf_include_buffers, args->print_args->wbf_include_columns,
+                         args->print_args->wbf_field_dict, args->print_args->wbf_column_cache, args->print_args->wbf_column_count);
+
+    epan_dissect_reset(&args->edt);
+
+    return !ferror(args->fh);
+}
+
+cf_print_status_t
+cf_write_wbf_packets(capture_file *cf, print_args_t *print_args)
+{
+    write_packet_callback_args_t callback_args;
+    FILE *fh;
+    psp_return_t ret;
+
+    fh = ws_fopen(print_args->file, "wb"); /* Binary mode for WBF */
+    if (fh == NULL)
+        return CF_PRINT_OPEN_ERROR; /* attempt to open destination failed */
+
+    /* Set large output buffer for better I/O performance (1 MB) */
+    setvbuf(fh, NULL, _IOFBF, 1048576);
+
+    /* Initialize field dictionary if not already done */
+    if (print_args->wbf_field_dict == NULL)
+    {
+        print_args->wbf_field_dict = g_hash_table_new_full(g_direct_hash, g_direct_equal, NULL, wbf_field_cache_entry_free);
+    }
+
+    /* Initialize column cache for SAME_AS_PREVIOUS optimization */
+    if (print_args->wbf_include_columns && print_args->wbf_column_cache == NULL)
+    {
+        /* Count visible columns */
+        print_args->wbf_column_count = 0;
+        for (int i = 0; i < cf->cinfo.num_cols; i++)
+        {
+            if (get_column_visible(i))
+            {
+                print_args->wbf_column_count++;
+            }
+        }
+
+        /* Allocate cache array */
+        if (print_args->wbf_column_count > 0)
+        {
+            print_args->wbf_column_cache = g_malloc0(print_args->wbf_column_count * sizeof(char *));
+        }
+    }
+
+    write_wbf_preamble(fh, cf->filename, &cf->cinfo, print_args->wbf_include_buffers, print_args->wbf_include_columns);
+    if (ferror(fh))
+    {
+        fclose(fh);
+        return CF_PRINT_WRITE_ERROR;
+    }
+
+    callback_args.fh = fh;
+    callback_args.print_args = print_args;
+    epan_dissect_init(&callback_args.edt, cf->epan, true, true);
+
+    /* Iterate through the list of packets, writing them in WBF format */
+    ret = process_specified_records(cf, &print_args->range, "Writing WBF",
+                                    "selected packets", true,
+                                    write_wbf_packet, &callback_args, true);
+
+    epan_dissect_cleanup(&callback_args.edt);
+
+    switch (ret)
+    {
+
+    case PSP_FINISHED:
+        /* Completed successfully. */
+        break;
+
+    case PSP_STOPPED:
+        /* Well, the user decided to abort the export. */
+        break;
+
+    case PSP_FAILED:
+        /* Error while exporting. */
+        fclose(fh);
+        return CF_PRINT_WRITE_ERROR;
+    }
+
+    /* Write end-of-packets marker */
+    write_wbf_finale(fh);
+    if (ferror(fh))
+    {
+        fclose(fh);
+        return CF_PRINT_WRITE_ERROR;
+    }
+
+    /* Clean up field dictionary */
+    if (print_args->wbf_field_dict != NULL)
+    {
+        g_hash_table_destroy(print_args->wbf_field_dict);
+        print_args->wbf_field_dict = NULL;
+    }
+
+    /* Clean up column cache */
+    if (print_args->wbf_column_cache != NULL)
+    {
+        for (uint32_t i = 0; i < print_args->wbf_column_count; i++)
+        {
+            if (print_args->wbf_column_cache[i] != NULL)
+            {
+                g_free(print_args->wbf_column_cache[i]);
+            }
+        }
+        g_free(print_args->wbf_column_cache);
+        print_args->wbf_column_cache = NULL;
+        print_args->wbf_column_count = 0;
+    }
+
+    /* XXX - check for an error */
+    fclose(fh);
+
+    return CF_PRINT_OK;
+}
